import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"SidebarDrawerContent (ue-sidebar-drawer-content)","description":"","frontmatter":{"sidebarPos":4,"sidebarTitle":"Sidebar Drawer Content"},"headers":[],"relativePath":"guide/components/layouts/sidebar-drawer-content.md","filePath":"guide/components/layouts/sidebar-drawer-content.md","lastUpdated":1777448653000}'),a={name:"guide/components/layouts/sidebar-drawer-content.md"},n=o(`<h1 id="sidebardrawercontent-ue-sidebar-drawer-content" tabindex="-1">SidebarDrawerContent (<code>ue-sidebar-drawer-content</code>) <a class="header-anchor" href="#sidebardrawercontent-ue-sidebar-drawer-content" aria-label="Permalink to &quot;SidebarDrawerContent (\`ue-sidebar-drawer-content\`)&quot;">​</a></h1><p><code>SidebarDrawerContent</code> is the innermost layout component — the actual <code>v-navigation-drawer</code>. It renders the logo/app header, the navigation list, and the user footer with profile menu, logout, and About dialog.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This is an internal component. You do not use it directly.</p></div><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│  [prepend]                          │</span></span>
<span class="line"><span>│  ┌────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │ mini-logo  App Name            │ │ ← app info header</span></span>
<span class="line"><span>│  │            app@email.com   ◀◀  │ │ ← rail toggle (desktop only)</span></span>
<span class="line"><span>│  └────────────────────────────────┘ │</span></span>
<span class="line"><span>│  ─────────────────────────────────  │</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>│  ue-navigation-group (items)        │ ← main nav list</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>│  [append]                           │</span></span>
<span class="line"><span>│  ─────────────────────────────────  │</span></span>
<span class="line"><span>│  ┌────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │ avatar  User Name          ▼   │ │ ← user info + profile toggle</span></span>
<span class="line"><span>│  │         user@email.com         │ │</span></span>
<span class="line"><span>│  └────────────────────────────────┘ │</span></span>
<span class="line"><span>│  [ue-navigation-group profileMenu]  │ ← collapsible profile menu</span></span>
<span class="line"><span>│  Logout                             │</span></span>
<span class="line"><span>│  About                              │</span></span>
<span class="line"><span>│  [bottom slot]                      │ ← impersonation toolbar, etc.</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><h2 id="prepend-—-app-header" tabindex="-1">Prepend — app header <a class="header-anchor" href="#prepend-—-app-header" aria-label="Permalink to &quot;Prepend — app header&quot;">​</a></h2><ul><li>Displays the app name and email from <code>store.getters.appName</code> / <code>store.getters.appEmail</code>.</li><li>The avatar shows the <code>miniSymbol</code> SVG icon.</li><li>A <strong>rail toggle</strong> button (<code>mdi-chevron-double-left</code> / <code>mdi-chevron-double-right</code>) is shown on desktop when <code>lgAndUp</code> is true. Clicking emits <code>rail-toggle</code>. <ul><li>When <code>railManual</code> is <code>true</code> (drawer is manually collapsed) the icon points right; otherwise left.</li></ul></li></ul><h2 id="body-—-navigation" tabindex="-1">Body — navigation <a class="header-anchor" href="#body-—-navigation" aria-label="Permalink to &quot;Body — navigation&quot;">​</a></h2><p>Renders <code>ue-navigation-group</code> with:</p><ul><li><code>items</code> — the full nav tree</li><li><code>hideIcons</code> — switches to text-only mode</li><li><code>showTooltip</code> — enabled when in rail mode without hover expand (<code>rail &amp;&amp; !isHoverable</code>), so hovering a collapsed item shows its label in a tooltip</li></ul><h2 id="append-—-user-footer" tabindex="-1">Append — user footer <a class="header-anchor" href="#append-—-user-footer" aria-label="Permalink to &quot;Append — user footer&quot;">​</a></h2><p>Visible only when the user is authenticated (<code>!store.getters.isGuest</code>):</p><table><thead><tr><th>Element</th><th>Description</th></tr></thead><tbody><tr><td>Avatar</td><td>Shows <code>userProfile.avatar_url</code>; clicking calls <code>$openProfileDialog</code></td></tr><tr><td>Name / email</td><td>From <code>userProfile.name</code> and <code>userProfile.email</code>; email has a tooltip</td></tr><tr><td>Profile toggle</td><td><code>mdi-chevron-down/up</code> button; emits <code>update:profileMenuOpen</code></td></tr><tr><td>Profile menu</td><td><code>ue-navigation-group</code> with <code>profileMenu</code> items; shown in a <code>v-expand-transition</code></td></tr><tr><td>Logout</td><td><code>ue-logout-modal</code> with CSRF token; shows tooltip when in collapsed rail mode</td></tr><tr><td>About</td><td><code>v-dialog</code> showing package versions, app name, env, and debug state (superadmin only)</td></tr></tbody></table><p>The <code>bottom</code> slot is rendered after the user section (used for impersonation toolbar etc.).</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>Array</code></td><td>Yes</td><td>—</td><td>Main navigation items</td></tr><tr><td><code>profileMenu</code></td><td><code>Array</code></td><td>No</td><td><code>[]</code></td><td>Profile popover navigation items</td></tr><tr><td><code>miniSymbol</code></td><td><code>String</code></td><td>No</td><td><code>&#39;main-logo-dark&#39;</code></td><td>SVG symbol for the prepend avatar</td></tr><tr><td><code>profileMenuOpen</code></td><td><code>Boolean</code></td><td>No</td><td><code>false</code></td><td>Controls the profile menu expand state</td></tr><tr><td><code>status</code></td><td><code>Boolean</code></td><td>Yes</td><td>—</td><td>Drawer open/closed (<code>v-navigation-drawer</code> <code>model-value</code>)</td></tr><tr><td><code>rail</code></td><td><code>Boolean</code></td><td>Yes</td><td>—</td><td>Icon-only rail mode</td></tr><tr><td><code>isHoverable</code></td><td><code>Boolean</code></td><td>Yes</td><td>—</td><td><code>expand-on-hover</code> on the drawer</td></tr><tr><td><code>hideIcons</code></td><td><code>Boolean</code></td><td>Yes</td><td>—</td><td>Passed to <code>ue-navigation-group</code></td></tr><tr><td><code>options</code></td><td><code>Object</code></td><td>Yes</td><td>—</td><td>Contains <code>location</code>, <code>railWidth</code>, etc.</td></tr><tr><td><code>width</code></td><td><code>Number|String</code></td><td>Yes</td><td>—</td><td>Drawer width</td></tr><tr><td><code>effectivePersistent</code></td><td><code>Boolean</code></td><td>Yes</td><td>—</td><td>Vuetify <code>persistent</code></td></tr><tr><td><code>effectivePermanent</code></td><td><code>Boolean</code></td><td>Yes</td><td>—</td><td>Vuetify <code>permanent</code></td></tr><tr><td><code>effectiveTemporary</code></td><td><code>Boolean</code></td><td>No</td><td><code>false</code></td><td>Vuetify <code>temporary</code></td></tr><tr><td><code>railManual</code></td><td><code>Boolean</code></td><td>Yes</td><td>—</td><td>Whether the user manually collapsed to rail</td></tr></tbody></table><h2 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h2><table><thead><tr><th>Event</th><th>Payload</th><th>Description</th></tr></thead><tbody><tr><td><code>update:status</code></td><td><code>Boolean</code></td><td>Drawer open/close state change</td></tr><tr><td><code>update:profileMenuOpen</code></td><td><code>Boolean</code></td><td>Profile menu expand toggle</td></tr><tr><td><code>activateMenu</code></td><td>event</td><td>Forwarded from <code>ue-navigation-group</code> profile menu</td></tr><tr><td><code>rail-toggle</code></td><td>—</td><td>Rail toggle button clicked</td></tr></tbody></table><h2 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h2><table><thead><tr><th>Slot</th><th>Description</th></tr></thead><tbody><tr><td><code>bottom</code></td><td>Appended after the user footer section in <code>[append]</code></td></tr></tbody></table><h2 id="about-dialog" tabindex="-1">About dialog <a class="header-anchor" href="#about-dialog" aria-label="Permalink to &quot;About dialog&quot;">​</a></h2><p>The <strong>About</strong> entry is only visible when <code>store.getters.versions</code> is populated and the user is not a guest or a client. For superadmins it additionally shows <code>appName</code>, <code>appEnv</code>, and <code>appDebug</code> with colour-coded chips.</p>`,22),s=[n];function r(i,c,l,p,h,u){return d(),t("div",null,s)}const g=e(a,[["render",r]]);export{b as __pageData,g as default};
